    defaultTagName: "div",
    props: mergeProps<"div">(
      {
        className: cn(
          "label-mono flex h-8 shrink-0 items-center gap-hair rounded-sheet px-2 text-ink-3 transition-[margin,opacity] duration-200 ease-linear group-data-[collapsible=icon]:-mt-8 group-data-[collapsible=icon]:opacity-0 [&>svg]:size-4 [&>svg]:shrink-0",
          className,
