      {
        className: cn(
          "absolute top-3.5 right-3 flex aspect-square w-5 cursor-pointer items-center justify-center rounded-sheet p-0 text-ink-2 transition-colors group-data-[collapsible=icon]:hidden after:absolute after:-inset-2 hover:bg-paper-3 hover:text-ink md:after:hidden [&>svg]:size-4 [&>svg]:shrink-0",
          className,
        ),
      },
      props,
    ),
    render,
    state: {
      slot: "sidebar-group-action",
      sidebar: "group-action",
    },
  })
